SELECT Song_Name, Song_release_year
FROM singer
WHERE Age = (SELECT MIN(Age) FROM singer);

SELECT Song_Name
FROM singer
WHERE Age > (SELECT AVG(Age) FROM singer);

SELECT Name, Capacity
FROM stadium
WHERE Average = (SELECT MAX(Average) FROM stadium);

SELECT PetType, MAX(weight) AS max_weight
FROM Pets
GROUP BY PetType;

SELECT s.Fname, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT hp.StuID, COUNT(*) AS pet_count
FROM Has_Pet hp
GROUP BY hp.StuID;

SELECT cm.Maker, ml.Model
FROM car_makers cm
JOIN model_list ml ON ml.Maker = cm.Id;

SELECT Airline, Abbreviation
FROM airlines
WHERE Country = 'USA';

SELECT Name
FROM shop
WHERE Number_products > (SELECT AVG(Number_products) FROM shop);

SELECT Name
FROM shop
WHERE Number_products > (SELECT AVG(Number_products) FROM shop);

SELECT Template_Type_Code
FROM Ref_Template_Types
WHERE Template_Type_Description = 'Book';

SELECT Name
FROM teacher
ORDER BY CAST(Age AS INTEGER) ASC;

SELECT Name
FROM teacher
ORDER BY CAST(Age AS INTEGER) ASC;

SELECT COUNT(*) AS num_visitors_below_30
FROM visitor
WHERE Age < 30;

SELECT AVG(Num_of_Staff) AS avg_staff
FROM museum
WHERE CAST(Open_Year AS INTEGER) < 2009;

SELECT loser_name, winner_name
FROM matches
WHERE minutes = (SELECT MAX(minutes) FROM matches);

SELECT name, tonnage
FROM ship
ORDER BY name DESC;

SELECT name, result
FROM battle
WHERE bulgarian_commander <> 'Boril';

SELECT zip_postcode
FROM Addresses
WHERE city = 'Port Chelsea';

SELECT section_name
FROM Sections
ORDER BY section_name DESC;

SELECT other_student_details
FROM Students
ORDER BY last_name DESC, first_name DESC, middle_name DESC;

SELECT Title
FROM Cartoon
WHERE Directed_by = 'Ben Jones';

SELECT COUNT(*) AS number_of_cartoones
FROM Cartoon
WHERE Written_by = 'Joseph Kuhr';

SELECT Episode, Rating
FROM TV_series
ORDER BY Rating;

SELECT p.Name
FROM people p
JOIN poker_player pp ON p.People_ID = pp.People_ID;

SELECT Nationality, COUNT(*) AS Num_People
FROM people
GROUP BY Nationality;

SELECT contestant_number, contestant_name
FROM CONTESTANTS
ORDER BY contestant_name DESC;

SELECT contestant_name
FROM CONTESTANTS
WHERE contestant_name <> 'Jessie Alloway';

SELECT COUNT(*) AS vote_count
FROM VOTES
WHERE state IN ('NY', 'CA');

SELECT contestant_name
FROM CONTESTANTS
WHERE contestant_name LIKE '%Al%';

SELECT AVG(LifeExpectancy) AS average_life_expectancy
FROM country
WHERE Continent = 'Africa' AND GovernmentForm LIKE '%Republic%';

SELECT MAX(Share) AS max_share, MIN(Share) AS min_share
FROM performance
WHERE Type <> 'Live final';

SELECT Record_Company, COUNT(*) AS orchestra_count
FROM orchestra
GROUP BY Record_Company;

SELECT COUNT(*) 
FROM Friend 
WHERE student_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle');

SELECT COUNT(*) AS like_count
FROM Likes
WHERE liked_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle');

SELECT t.cost_of_treatment AS cost, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT COUNT(*) 
FROM Dogs 
WHERE CAST(age AS REAL) < (SELECT AVG(CAST(age AS REAL)) FROM Dogs);

